#include <vector>
#include <cstddef>
#include <cmath>
#include <algorithm>
#include <omp.h>

struct COOElement {
   size_t row, column;
   double value;
};

void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    x.assign(N, 0.0);
    if (N == 0) return;
    if (b.size() != N) return; // basic guard; could also throw in real code

    // Convert COO -> CSR for safe, deterministic parallel SpMV without atomics.
    std::vector<size_t> rowPtr(N + 1, 0);
    for (const auto& e : A) {
        if (e.row < N && e.column < N) rowPtr[e.row + 1]++;
    }
    for (size_t i = 0; i < N; ++i) rowPtr[i + 1] += rowPtr[i];

    std::vector<size_t> colInd(rowPtr[N]);
    std::vector<double> values(rowPtr[N]);

    std::vector<size_t> next = rowPtr;
    for (const auto& e : A) {
        if (e.row >= N || e.column >= N) continue;
        size_t pos = next[e.row]++;
        colInd[pos] = e.column;
        values[pos] = e.value;
    }

    // Helper lambdas: y = A*x and y = A^T*x in CSR (A stored by rows).
    auto spmv = [&](const std::vector<double>& in, std::vector<double>& out) {
        out.assign(N, 0.0);
        #pragma omp parallel for schedule(static)
        for (size_t i = 0; i < N; ++i) {
            double sum = 0.0;
            for (size_t p = rowPtr[i]; p < rowPtr[i + 1]; ++p) {
                sum += values[p] * in[colInd[p]];
            }
            out[i] = sum;
        }
    };

    auto spmv_transpose = [&](const std::vector<double>& in, std::vector<double>& out) {
        // Need atomics because many rows contribute to same column.
        out.assign(N, 0.0);
        #pragma omp parallel for schedule(static)
        for (size_t i = 0; i < N; ++i) {
            double xi = in[i];
            for (size_t p = rowPtr[i]; p < rowPtr[i + 1]; ++p) {
                size_t j = colInd[p];
                double v = values[p] * xi;
                #pragma omp atomic
                out[j] += v;
            }
        }
    };

    // Conjugate Gradient on normal equations: (A^T A) x = A^T b
    // Works for general (possibly nonsymmetric) A; assumes consistent/solvable.
    const int maxIters = std::max<int>(1000, static_cast<int>(10 * N));
    const double tol = 1e-12;

    std::vector<double> Atb(N, 0.0);
    spmv_transpose(b, Atb);

    // r = Atb - (A^T A) x; with x=0 => r=Atb
    std::vector<double> r = Atb;
    std::vector<double> p = r;

    auto dot = [&](const std::vector<double>& u, const std::vector<double>& v) -> double {
        double s = 0.0;
        #pragma omp parallel for reduction(+:s) schedule(static)
        for (size_t i = 0; i < N; ++i) s += u[i] * v[i];
        return s;
    };

    double rr = dot(r, r);
    if (std::sqrt(rr) <= tol) return;

    std::vector<double> Ap_tmp(N, 0.0), Ap(N, 0.0);

    for (int k = 0; k < maxIters; ++k) {
        // Ap = (A^T A) p
        spmv(p, Ap_tmp);              // Ap_tmp = A p
        spmv_transpose(Ap_tmp, Ap);   // Ap = A^T (A p)

        double pAp = dot(p, Ap);
        if (std::abs(pAp) < 1e-30) break;

        double alpha = rr / pAp;

        #pragma omp parallel for schedule(static)
        for (size_t i = 0; i < N; ++i) {
            x[i] += alpha * p[i];
            r[i] -= alpha * Ap[i];
        }

        double rr_new = dot(r, r);
        if (std::sqrt(rr_new) <= tol) break;

        double beta = rr_new / rr;

        #pragma omp parallel for schedule(static)
        for (size_t i = 0; i < N; ++i) {
            p[i] = r[i] + beta * p[i];
        }

        rr = rr_new;
    }
}
